import SwiftUI
import AuthenticationServices
struct LoginView:View {@EnvironmentObject var store:AppStore;@Environment(\.dismiss) var dismiss;@State private var email="";@State private var code="";@State private var nonce:String?;@State private var sent=false
 var body:some View{NavigationStack{Form{Section{Text("Your card. Your name.").font(.title.bold());Text("Keep picks across devices and let friends tail your cards.")};if store.configuration?.auth==nil{Section{Text("Apple and email sign-in are waiting for the app owner’s authentication setup. You can still make picks and preview posters.")}}else{Section{SignInWithAppleButton(.continue){r in do{let n=try AuthService.nonce();nonce=n;r.nonce=AuthService.hash(n);r.requestedScopes=[.email,.fullName]}catch{store.message=error.localizedDescription}}onCompletion:{result in store.run{let auth=try result.get();guard let credential=auth.credential as? ASAuthorizationAppleIDCredential,let data=credential.identityToken,let token=String(data:data,encoding:.utf8),let nonce else{throw APIError(message:"Apple sign-in did not return a token.",status:401)};try await store.apple(idToken:token,nonce:nonce)}}.frame(height:48)};Section("Email sign-in"){TextField("Email",text:$email).textContentType(.emailAddress).keyboardType(.emailAddress).textInputAutocapitalization(.never).autocorrectionDisabled();Button("Send code"){store.run{try await store.emailCode(email);sent=true}};if sent{TextField("Email code",text:$code).textContentType(.oneTimeCode).keyboardType(.numberPad);Button("Sign in"){store.run{try await store.verifyCode(email:email,code:code)}}}}}}.navigationTitle("OnlyFights account").toolbar{Button("Close"){dismiss()}}}}
}
struct ProfileView:View {@EnvironmentObject var store:AppStore;@State private var username="";@State private var deleting=false;@State private var restoring:SavedDraft?
 var body:some View{List{Section{Text(store.profile.map{"@"+$0.username} ?? "Your fight identity").font(.title.bold());if store.signedIn{TextField("Username",text:$username).textInputAutocapitalization(.never).autocorrectionDisabled();Button("Save username"){store.run{try await store.username(username)}}}else{Button("Sign in or create an account"){store.showLogin=true}}};if store.signedIn{Section("Saved event picks"){ForEach(store.savedDrafts,id:\.event){d in Button{restoring=d}label:{VStack(alignment:.leading){Text(d.draft.eventName);Text("\(d.draft.picks.count) picks · revision \(d.revision)").font(.caption).foregroundStyle(.secondary)}}}};Section("Saved tickets"){ForEach(store.savedTickets){t in VStack(alignment:.leading){Text(t.ticket.category).font(.headline);Text(t.ticket.legs.map{$0.label+" · "+$0.market}.joined(separator:"\n")).font(.caption);Text("Estimated \(americanOdds(t.ticket.legs.reduce(1){$0*$1.decimal})) · No wager recorded").font(.caption2).foregroundStyle(.secondary);Button("Remove ticket",role:.destructive){store.run{let _:ActionResponse=try await APIClient.request("tickets/"+t.id,method:"DELETE",body:Data("{}".utf8),token:store.token());try await store.loadAccount()}}}}};Section{Button("Sign out"){store.signOut()};Button("Delete account",role:.destructive){deleting=true}}};Section("About your picks"){if store.signedIn{NavigationLink("Your record"){RecordHistoryView()}};Text("Locks mean personal confidence, not guaranteed outcomes. A sportsbook account and its own confirmation are required to wager.");Link("Privacy & data",destination:APIClient.base.appendingPathComponent("privacy"));Text("Friends beta · 21+").font(.caption)}}.navigationTitle("Profile").task{if store.signedIn{store.run{try await store.loadAccount()}}}.onAppear{username=store.profile?.username ?? ""}.confirmationDialog("Delete your account and its picks, cards and tickets?",isPresented:$deleting,titleVisibility:.visible){Button("Delete my account",role:.destructive){store.run{try await store.deleteAccount()}}}.confirmationDialog("Replace the picks on this device with this cloud save?",isPresented:Binding(get:{restoring != nil},set:{if !$0{restoring=nil}}),titleVisibility:.visible){if let d=restoring{Button("Load saved picks"){store.run{try await store.selectEvent(d.event);try await store.loadCloud();store.tab=0}}}}}
}
